663	func (s *ManualCommitStrategy) extractSessionData(ctx context.Context, repo *git.Repository, shadowRef plumbing.Hash, sessionID string, filesTouched []string, agentType types.AgentType, liveTranscriptPath string, checkpointTranscriptStart int, isActive bool) (*ExtractedSessionData, error) {
664		ag, _ := agent.GetByAgentType(agentType) //nolint:errcheck // ag may be nil for unknown agent types; callers use type assertions so nil is safe
665		commit, err := repo.CommitObject(shadowRef)
666		if err != nil {
667			return nil, fmt.Errorf("failed to get commit object: %w", err)
668		}
669	
670		tree, err := commit.Tree()
671		if err != nil {
672			return nil, fmt.Errorf("failed to get commit tree: %w", err)
673		}
674	
675		data := &ExtractedSessionData{}
676		// sessionID is already an "entire session ID" (with date prefix)
677		metadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
678	
679		// Extract transcript — prefer the live file when available, fall back to shadow branch.
680		// The shadow branch copy may be stale if the last turn ended without code changes
681		// (SaveStep is only called when there are file modifications).
682		var fullTranscript string
683		if liveTranscriptPath != "" {
684			// Ensure transcript file exists (OpenCode creates it lazily via `opencode export`).
685			// Only wait for flush when the session is active — for idle/ended sessions the
686			// transcript is already fully flushed (the Stop hook completed the flush).
687			if isActive {
688				prepareTranscriptIfNeeded(ctx, ag, liveTranscriptPath)
689			}
690			if liveData, readErr := os.ReadFile(liveTranscriptPath); readErr == nil && len(liveData) > 0 { //nolint:gosec // path from session state
691				fullTranscript = string(liveData)
692			}
693		}
694		if fullTranscript == "" {
695			// Fall back to shadow branch copy
696			if file, fileErr := tree.File(metadataDir + "/" + paths.TranscriptFileName); fileErr == nil {
697				if content, contentErr := file.Contents(); contentErr == nil {
698					fullTranscript = content
699				}
700			} else if file, fileErr := tree.File(metadataDir + "/" + paths.TranscriptFileNameLegacy); fileErr == nil {
701				if content, contentErr := file.Contents(); contentErr == nil {
702					fullTranscript = content
703				}
704			}
705		}
706	
707		// Process transcript based on agent type
708		if fullTranscript != "" {
709			data.Transcript = []byte(fullTranscript)
710			data.FullTranscriptLines = countTranscriptItems(agentType, fullTranscript)
711			// Read prompts from shadow branch tree (source of truth after SaveStep)
712			if file, fileErr := tree.File(metadataDir + "/" + paths.PromptFileName); fileErr == nil {
713				if content, contentErr := file.Contents(); contentErr == nil && content != "" {
714					data.Prompts = splitPromptContent(content)
715				}
716			}
717			// Filesystem fallback (written at turn start, covers mid-turn commits)
718			if len(data.Prompts) == 0 {
719				data.Prompts = readPromptsFromFilesystem(ctx, sessionID)
720			}
721		}
722	
723		// Use tracked files from session state (not all files in tree)
724		data.FilesTouched = filesTouched
725	
726		// Calculate token usage from the extracted transcript portion
727		if len(data.Transcript) > 0 {
728			data.TokenUsage = agent.CalculateTokenUsage(ctx, ag, data.Transcript, checkpointTranscriptStart, "") //TODO: why do we not use here subagents dir?
729		}
730	
731		return data, nil
732	}
